// And groups predicates with the AND operator between them.
func And(predicates ...predicate.InspectionPlan) predicate.InspectionPlan {
	return predicate.InspectionPlan(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
